// Turns red once the last feed is this many minutes old.
const DUE = 12 * 60;
const AMBER = '#FFB547';
const RED = '#FF5A5F';

function ago(minutes) {
  if (minutes < 1) return 'Just now';
  if (minutes < 60) return minutes + ' min ago';
  const hours = Math.floor(minutes / 60);
  const rest = minutes % 60;
  if (hours >= 10 || rest === 0) return hours + ' h ago';
  return hours + ' h ' + rest + ' min ago';
}

function clock(at) {
  return at.charAt(0) === '0' ? at.slice(1) : at;
}

function who(row) {
  if (row.by.me) return 'You';
  return row.by.name || 'Someone';
}

function render(ctx) {
  const d = ctx.data;
  const last = d.last;
  const due = !last || last.minutesAgo >= DUE;
  const tone = due ? RED : AMBER;

  // The paw is cut out of the disc, so it shows in tinted and clear mode.
  const feed = { type: 'button', action: 'feed', children: [
    { type: 'symbol', name: 'pawprint.circle.fill', size: ctx.family === 'medium' ? 64 : 44, color: tone,
      accent: true } ] };

  const undo = last && last.by.me && last.minutesAgo < 60 && { type: 'button', action: 'undo', rowId: last.id,
    children: [
      { type: 'symbol', name: 'arrow.uturn.backward', size: 12, weight: 'bold', color: '#F6E7D0',
        frame: { width: 30, height: 30 }, background: '#F6E7D022', clip: 'circle' } ] };

  const headline = !last ? 'Not fed yet' : due ? 'Feed me!' : ago(last.minutesAgo);
  const detail = !last
    ? 'Tap the paw after a meal'
    : due
      ? who(last) + ' fed ' + ago(last.minutesAgo).replace(' ago', '') + ' ago'
      : who(last) + ' at ' + clock(last.at);

  const status = {
    type: 'vstack', align: 'leading', spacing: 4,
    frame: { maxWidth: 'infinity', alignment: 'leading' },
    children: [
      { type: 'hstack', spacing: 5, children: [
        { type: 'symbol', name: 'dog.fill', size: 13, color: '#F6E7D0' },
        { type: 'text', value: 'Dog fed', size: 13, weight: 'semibold', color: '#F6E7D0CC' } ] },
      { type: 'text', value: headline, size: ctx.family === 'medium' ? 28 : 22, weight: 'bold', design: 'rounded',
        color: due ? RED : '#FFFFFF', lineLimit: 1, minScale: 0.5 },
      { type: 'text', value: detail, size: 12, weight: 'medium', color: '#F6E7D0B3', lineLimit: 2, minScale: 0.7 },
    ],
  };

  const count = { type: 'text', value: d.today === 1 ? '1 meal today' : d.today + ' meals today', size: 11,
    weight: 'semibold', color: '#F6E7D099', lineLimit: 1, minScale: 0.6 };

  if (ctx.family === 'medium') {
    return {
      type: 'hstack', spacing: 16, padding: 16,
      frame: { maxWidth: 'infinity', maxHeight: 'infinity' },
      widgetBackground: { gradient: 'linear', stops: ['#3B2A1E', '#24180F'], from: 'top', to: 'bottom' },
      children: [
        { type: 'vstack', align: 'leading', spacing: 8,
          frame: { maxWidth: 'infinity', maxHeight: 'infinity', alignment: 'topLeading' },
          children: [status, { type: 'spacer', minLength: 0 }, count] },
        { type: 'vstack', spacing: 6, children: [feed, undo] },
      ],
    };
  }

  return {
    type: 'vstack', align: 'leading', spacing: 0, padding: 14,
    frame: { maxWidth: 'infinity', maxHeight: 'infinity', alignment: 'topLeading' },
    widgetBackground: { gradient: 'linear', stops: ['#3B2A1E', '#24180F'], from: 'top', to: 'bottom' },
    children: [
      status,
      { type: 'spacer', minLength: 0 },
      { type: 'hstack', align: 'bottom', children: [
        undo || count,
        { type: 'spacer', minLength: 0 },
        feed ] },
    ],
  };
}
